+/**
+ * Narrows the customer list. A customer matches when it satisfies both parts.
+ *
+ * @param name     whitespace-separated terms; every term must appear, ignoring case and
+ *                 accents, in the customer's first name or last name. Blank matches every name.
+ * @param statuses statuses a customer may have; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+}
